1	// Concatenate src/*.js into build/bundle.js and write build/manifest.json.
2	// --clean removes build/ first (release engineering only; see README).
3	import { createHash } from "node:crypto";
4	import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
5	
6	const sha = (s: string) => createHash("sha256").update(s).digest("hex").slice(0, 16);
7	
8	export function buildOutputs(srcDir = "src"): { bundle: string; manifest: string } {
9	  const files = readdirSync(srcDir).filter((f) => f.endsWith(".js")).sort();
10	  const sources = files.map((f) => [f, readFileSync(`${srcDir}/${f}`, "utf8")] as const);
11	  const body = sources.map(([f, s]) => `// ---- src/${f}\n${s}`).join("\n");
12	  const bundle = `// pricewidget bundle ${sha(body)}\n${body}`;
13	  const manifest = JSON.stringify({ bundle: sha(body), files: Object.fromEntries(sources.map(([f, s]) => [f, sha(s)])) }, null, 2) + "\n";
14	  return { bundle, manifest };
15	}
16	
17	export function main(argv: string[]): void {
18	  if (argv.includes("--clean")) rmSync("build", { recursive: true, force: true });
19	  mkdirSync("build", { recursive: true });
20	  const { bundle, manifest } = buildOutputs();
21	  writeFileSync("build/bundle.js", bundle);
22	  writeFileSync("build/manifest.json", manifest);
23	  process.stdout.write(`built build/bundle.js (${bundle.length} bytes)\n`);
24	}
25	
26	if (import.meta.url === `file://${process.argv[1]}`) main(process.argv.slice(2));
